import math

def integer_rdp(q, z, alpha):
    terms=[math.lgamma(alpha+1)-math.lgamma(i+1)-math.lgamma(alpha-i+1)+i*math.log(q)+(alpha-i)*math.log1p(-q)+(i*i-i)/(2*z*z) for i in range(alpha+1)]
    m=max(terms)
    return (m+math.log(sum(math.exp(t-m) for t in terms)))/(alpha-1)

def epsilon(q,z,T,delta=1e-9):
    candidates=[]
    for a in range(2,129):
        r=T*integer_rdp(q,z,a)
        eps=r-(math.log(delta)+math.log(a))/(a-1)+math.log((a-1)/a)
        candidates.append((eps,a))
    return min(candidates)
